import { createRootRoute, HeadContent, Scripts } from "@tanstack/react-router";

import { PENDING_VIEW_SCRIPT } from "#/lib/sharedLink";
import { THEME_SCRIPT } from "#/lib/theme";
import appCss from "../styles.css?url";

/** Social cards need absolute URLs, so they name the primary domain. */
const SITE_URL = "https://slopsubs.com/";
const TITLE = "slopsubs: subscription value per task";
const DESCRIPTION =
	"Effective cost per task on AI coding subscriptions, from measured weekly caps.";
/** Regenerated by scripts/render-brand-images.ts. */
const CARD = { url: `${SITE_URL}og.png`, width: "1200", height: "630" };

export const Route = createRootRoute({
	head: () => ({
		meta: [
			{ charSet: "utf-8" },
			{ name: "viewport", content: "width=device-width, initial-scale=1" },
			{ title: TITLE },
			{ name: "description", content: DESCRIPTION },
			{ property: "og:type", content: "website" },
			{ property: "og:site_name", content: "slopsubs" },
			{ property: "og:url", content: SITE_URL },
			{ property: "og:title", content: TITLE },
			{ property: "og:description", content: DESCRIPTION },
			{ property: "og:image", content: CARD.url },
			{ property: "og:image:width", content: CARD.width },
			{ property: "og:image:height", content: CARD.height },
			{
				property: "og:image:alt",
				content:
					"Chart of intelligence index against effective cost per task, by subscription and model",
			},
			{ name: "twitter:card", content: "summary_large_image" },
			{ name: "twitter:title", content: TITLE },
			{ name: "twitter:description", content: DESCRIPTION },
			{ name: "twitter:image", content: CARD.url },
		],
		links: [
			{ rel: "icon", href: "/favicon.svg", type: "image/svg+xml" },
			{ rel: "apple-touch-icon", href: "/apple-touch-icon.png" },
			{ rel: "preconnect", href: "https://fonts.googleapis.com" },
			{
				rel: "stylesheet",
				href: "https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&display=swap",
			},
			{ rel: "stylesheet", href: appCss },
		],
	}),
	shellComponent: RootDocument,
});

function RootDocument({ children }: { children: React.ReactNode }) {
	return (
		// The head scripts set data-theme and data-view-pending before hydration.
		<html lang="en" suppressHydrationWarning>
			<head>
				{/* oxlint-disable-next-line react/no-danger -- static script, no user input */}
				<script dangerouslySetInnerHTML={{ __html: THEME_SCRIPT }} />
				{/* oxlint-disable-next-line react/no-danger -- static script, no user input */}
				<script dangerouslySetInnerHTML={{ __html: PENDING_VIEW_SCRIPT }} />
				<HeadContent />
			</head>
			<body>
				{children}
				<Scripts />
			</body>
		</html>
	);
}
